\title{Rigidity and Strict Subadditivity of the Universal Coding Price}
\author{Aristotle}
\date{22 August 2026}

\begin{document}
\maketitle

\begin{abstract}
For a class of probability laws $\{p_\theta\}_{\theta\in\Theta}$ on a finite message
space $\X$, the minimax pointwise regret of universal coding equals $\log_2 C_S$, where
$C_S = \sum_x \sup_\theta p_\theta(x)$ is the Shtarkov sum of the class. The elementary
bounds $1 \le C_S \le |\Theta|$ have been known since the subject began; this paper
carries out the corresponding equality analysis and cashes it in for the memoryless
class. The organising observation is an exact conservation law: for a finite class,
$C_S + \Omega = |\Theta|$, where
$\Omega = \sum_x\big(\sum_\theta p_\theta(x) - \max_\theta p_\theta(x)\big) \ge 0$ is the
\emph{overlap}, the probability mass shared by the sources. From it we obtain: $C_S =
|\Theta|$ iff the sources are mutually singular, equivalently iff they admit pairwise
disjoint full-mass supports; $C_S = 1$ iff all sources coincide; the exact two-source
formula $C_S = 1 + \dTV(p,q)$; a total-variation sandwich; stability of the upper
endpoint, both for a single close pair and for all pairs simultaneously; and the equality
cases of the monotonicity and sufficient-statistic bounds. Applied to the tied-product
construction, the same analysis shows that $C_S(\mathrm{tied}) = C_S^{(1)}C_S^{(2)}$ holds
iff every pair of block outcomes admits a common maximum-likelihood parameter, with a
finiteness-free strict variant driven by a quantitative envelope deficiency. For the
memoryless class on an alphabet of $m\ge2$ letters this yields $C_S(1) = m$,
$C_S(n_1+n_2) < C_S(n_1)C_S(n_2)$ for $n_1,n_2\ge1$, strict subadditivity of the minimax
regret in block length, and $C_S(n) < m^n$ for every $n \ge 2$.
\end{abstract}

\section{Introduction}

Let $\X$ be a finite set of messages and $\mathcal{P} = \{p_\theta\}_{\theta\in\Theta}$ a
family of probability distributions on $\X$, a \emph{source class}. A coder who knows
$\theta$ achieves codelength $\log_2(1/p_\theta(x))$; a universal coder must commit to a
single $q$ and pay $\log_2(1/q(x))$. The \emph{pointwise regret} relative to the best
member in hindsight is
\[
R(q,x) \;=\; \log_2 \frac{\sup_\theta p_\theta(x)}{q(x)} .
\]
Shtarkov's theorem states that $\min_q\max_x R(q,x)$ is attained by the \emph{normalised
maximum likelihood} distribution $q^\star(x) = \sup_\theta p_\theta(x)/C_S$ with
\[
C_S \;=\; \sum_{x\in\X}\ \sup_{\theta\in\Theta} p_\theta(x),
\]
and equals $\log_2 C_S$, the same regret at every message. Two bounds are immediate:
$C_S \ge \sum_x p_{\theta_0}(x) = 1$ for any fixed $\theta_0$; and, for a finite class,
$\sup_\theta p_\theta(x) \le \sum_\theta p_\theta(x)$ gives $C_S \le |\Theta|$, i.e.\ one
never pays more than the cost $\log_2|\Theta|$ of naming the source. Both are attained.
This paper determines exactly when, quantifies the deficiency when they are not attained,
and applies the resulting criteria to the memoryless class.

\section{Setting}

\begin{definition}[Source class]
A \emph{source class} on a finite set $\X$ with parameter set $\Theta$ is a family
$p : \Theta\times\X\to\mathbb{R}$ with $p_\theta(x)\ge0$ and $\sum_x p_\theta(x) = 1$ for
every $\theta$.
\end{definition}

\begin{definition}[Envelope, Shtarkov sum]
The \emph{maximum-likelihood envelope} is $\ph(x) = \sup_\theta p_\theta(x) \in [0,1]$;
the \emph{Shtarkov sum} is $C_S = \sum_{x\in\X}\ph(x)$ and the \emph{price of
universality} in bits is $\log_2 C_S$.
\end{definition}

\begin{definition}[Total variation, affinity]
For laws $p,q$ on $\X$, $\dTV(p,q) = \tfrac12\sum_x|p(x)-q(x)|\in[0,1]$, and the
\emph{affinity} of the pair is $1-\dTV(p,q) = \sum_x\min(p(x),q(x))$.
\end{definition}

\begin{definition}[Tied product]
Given classes $\mathcal{P}^{(1)}$ on $\X_1$ and $\mathcal{P}^{(2)}$ on $\X_2$ sharing the
\emph{same} parameter set $\Theta$, their \emph{tied product} is the class on
$\X_1\times\X_2$ with $p_\theta(x_1,x_2) = p^{(1)}_\theta(x_1)p^{(2)}_\theta(x_2)$.
\end{definition}

\begin{definition}[Memoryless class]
Let $\A$ be a finite alphabet with $m = |\A|$ letters and
$\Delta(\A) = \{\theta:\A\to[0,1] : \sum_a\theta(a)=1\}$. The \emph{memoryless class of
block length $n$} is the family on $\A^n$ with $p_\theta(x) = \prod_{i=1}^n\theta(x_i)$;
its Shtarkov sum is written $C_S(n)$. For $a\in\A$ the point mass
$\delta_a\in\Delta(\A)$ is $\delta_a(b) = \mathbf{1}[b=a]$.
\end{definition}

We use freely that $\theta(a)\le1$ for every letter and $\theta(a)+\theta(b)\le1$ for
distinct letters, both immediate from non-negativity and $\sum_b\theta(b)=1$.

\section{The conservation law}

\begin{definition}[Overlap]
For a finite class, $\displaystyle \Omega = \sum_{x\in\X}\Big(\sum_{\theta}p_\theta(x) - \ph(x)\Big)$.
\end{definition}

Each summand is non-negative, since $\ph(x)$ is one of the terms of the inner sum and the
remaining terms are non-negative; so $\Omega \ge 0$. It is the total probability mass not
claimed by the locally best source: the mass the class shares.

\begin{theorem}[Conservation law]\label{thm:cons}
For a finite class with $k = |\Theta|$ sources, $C_S + \Omega = k$.
\end{theorem}

\begin{proof}
Termwise, $\ph(x) + \big(\sum_\theta p_\theta(x)-\ph(x)\big) = \sum_\theta p_\theta(x)$.
Summing over $x$ and exchanging the order of summation gives
$\sum_\theta\sum_x p_\theta(x) = k$.
\end{proof}

Thus $C_S \le k$ is precisely $\Omega \ge 0$, and the deficiency $k - C_S$ is a
meaningful quantity: every result below is a statement about it.

\section{Rigidity at the endpoints}

\begin{definition}[Mutual singularity]
A class is \emph{mutually singular} if for every $x$ and every $\theta\ne\theta'$, at
least one of $p_\theta(x)$, $p_{\theta'}(x)$ vanishes.
\end{definition}

\begin{lemma}[Pointwise rigidity]\label{lem:ptwise}
For a finite class and fixed $x$, $\ph(x) = \sum_\theta p_\theta(x)$ if and only if at
most one source charges $x$.
\end{lemma}

\begin{proof}
($\Rightarrow$) Finiteness gives a maximiser $\theta_0$; then
$\sum_{\theta\ne\theta_0}p_\theta(x) = 0$ and, all terms being non-negative, each
vanishes. ($\Leftarrow$) If all sources vanish at $x$ both sides are $0$; otherwise the
unique charging source realises both the maximum and the total.
\end{proof}

\begin{theorem}[Rigidity of the maximal price]\label{thm:upper}
For a finite class, $C_S = k$ if and only if the class is mutually singular.
\end{theorem}

\begin{proof}
By Theorem~\ref{thm:cons}, $C_S = k$ iff $\Omega = 0$; a sum of non-negative terms
vanishes iff each term does, which by Lemma~\ref{lem:ptwise} is mutual singularity at
every message.
\end{proof}

\begin{theorem}[Support form]
$C_S = k$ if and only if there are pairwise disjoint $S_\theta\subseteq\X$ with
$p_\theta(S_\theta) = 1$ for every $\theta$.
\end{theorem}

\begin{proof}
If $C_S = k$, take $S_\theta = \{x : p_\theta(x)\ne 0\}$; disjointness is
Theorem~\ref{thm:upper} and each carries full mass. Conversely $\ph \ge p_\theta$ on
$S_\theta$, so $C_S \ge \sum_\theta p_\theta(S_\theta) = k$, and $C_S \le k$ always.
\end{proof}

\begin{theorem}[Strictness]
If $p_\theta(x) > 0$ and $p_{\theta'}(x) > 0$ for some $x$ and some $\theta\ne\theta'$,
then $C_S < k$.
\end{theorem}

\begin{theorem}[Rigidity of the free class]\label{thm:lower}
For any class, $C_S = 1$ if and only if $p_\theta(x) = p_{\theta'}(x)$ for all
$\theta,\theta',x$.
\end{theorem}

\begin{proof}
If all sources coincide then $\ph = p_{\theta_0}$ sums to $1$. Conversely fix
$\vartheta$; then $p_\vartheta \le \ph$ pointwise and $\sum_x p_\vartheta = \sum_x \ph = 1$,
so the non-negative differences sum to zero and hence vanish pointwise. As $\vartheta$
was arbitrary, all sources equal $\ph$.
\end{proof}

\begin{corollary}
If two members differ at some message then $C_S > 1$: the price of universality is
strictly positive. In bits, $\log_2 C_S = 0$ iff all sources coincide, and
$\log_2 C_S = \log_2 k$ iff the class is mutually singular.
\end{corollary}

\section{Total variation: exact formula, sandwich, stability}

\begin{theorem}[The price of a pair is a distance]\label{thm:pair}
For a class with exactly two members $p,q$, $\;C_S = 1 + \dTV(p,q)$.
\end{theorem}

\begin{proof}
$\ph(x) = \max(p(x),q(x)) = \tfrac12(p(x)+q(x)+|p(x)-q(x)|)$; summing and using
$\sum_x p = \sum_x q = 1$ gives $C_S = 1 + \dTV(p,q)$.
\end{proof}

Theorem~\ref{thm:pair} interpolates exactly between the rigidity theorems:
$\dTV = 0$ is Theorem~\ref{thm:lower}, and $\dTV = 1$ is Theorem~\ref{thm:upper} for
$k=2$. Two identities, proved by the same substitution, are used below:
\[
\sum_x (p(x)-q(x))_+ = \dTV(p,q), \qquad \sum_x\min(p(x),q(x)) = 1-\dTV(p,q).
\]

\begin{theorem}[Pairwise separation is a lower bound]
For any class and any $\theta,\theta'$, $\;1 + \dTV(p_\theta,p_{\theta'}) \le C_S$.
\end{theorem}

\begin{proof}
Restricting the parameter set to $\{\theta,\theta'\}$ lowers the envelope pointwise, hence
the Shtarkov sum; apply Theorem~\ref{thm:pair} to the pair.
\end{proof}

\begin{theorem}[Upper bound relative to a reference source]
For a finite class and any $\theta_0$,
$\;C_S \le 1 + \sum_\theta \dTV(p_\theta,p_{\theta_0})$.
\end{theorem}

\begin{proof}
Pointwise $p_\theta(x) \le p_{\theta_0}(x) + \sum_{\vartheta}(p_\vartheta(x)-p_{\theta_0}(x))_+$
for every $\theta$, hence the same bounds $\ph(x)$. Sum over $x$, exchange the order of
summation and apply the positive-part identity.
\end{proof}

\begin{theorem}[Stability: one close pair]\label{thm:stab}
For a finite class with $k$ sources and any $\theta\ne\theta'$,
\[
C_S \;\le\; k - 1 + \dTV(p_\theta,p_{\theta'}).
\]
\end{theorem}

\begin{proof}
Fix $x$ and let $\vartheta_0$ attain the envelope. At least one of $\theta,\theta'$
differs from $\vartheta_0$ and its mass survives in the non-maximal part, so
$\min(p_\theta(x),p_{\theta'}(x)) \le \sum_\vartheta p_\vartheta(x) - \ph(x)$. Summing
over $x$ yields $1-\dTV(p_\theta,p_{\theta'}) \le \Omega$, and Theorem~\ref{thm:cons}
converts this into the claim.
\end{proof}

\begin{theorem}[All-pairs stability]
For a finite class with $k$ sources,
\[
\sum_{\theta}\sum_{\theta'\ne\theta}\big(1-\dTV(p_\theta,p_{\theta'})\big)
\;\le\; k(k-1)\,\Omega \;=\; k(k-1)\,(k-C_S).
\]
\end{theorem}

\begin{proof}
The pointwise inequality in the proof of Theorem~\ref{thm:stab} holds for every ordered
pair of distinct indices at each message. Sum it over the $k(k-1)$ ordered pairs and then
over messages, and use the affinity identity; the final equality is
Theorem~\ref{thm:cons}.
\end{proof}

\section{Equality analysis of the structural laws}

\subsection{Monotonicity under parameter pruning}

Given $\iota:\Theta'\to\Theta$, the reindexed class $\{p_{\iota(\theta')}\}$ has a
pointwise smaller envelope, hence a smaller Shtarkov sum.

\begin{theorem}[Equality case of monotonicity]
The reindexed class has the same Shtarkov sum as the full class iff it reproduces the
envelope at every message: pruning parameters is free precisely when the pruned ones were
never maximisers.
\end{theorem}

\begin{proof}
A sum of pointwise inequalities is an equality iff each difference vanishes.
\end{proof}

\subsection{The tied product}

\begin{lemma}\label{lem:tiedpt}
For the tied product, $\ph(x_1,x_2) \le \ph^{(1)}(x_1)\ph^{(2)}(x_2)$, and
$\sum_{(x_1,x_2)}\ph^{(1)}(x_1)\ph^{(2)}(x_2) = C_S^{(1)}C_S^{(2)}$.
\end{lemma}

\begin{proof}
For each $\theta$ multiply the two envelope bounds (all quantities non-negative) and take
the supremum; the second claim is Fubini for a product of finite sums.
\end{proof}

\begin{theorem}[Submultiplicativity]
$C_S(\mathrm{tied}) \le C_S^{(1)}C_S^{(2)}$; in bits, the price is subadditive.
\end{theorem}

Applied to the blocks of a stationary parametric family this is precisely the hypothesis
of Fekete's lemma, guaranteeing convergence of the per-symbol price
$\frac1n\log_2 C_S(n)$.

\begin{theorem}[Equality criterion, finite parameter set]\label{thm:tiedeq}
For finite $\Theta$, $C_S(\mathrm{tied}) = C_S^{(1)}C_S^{(2)}$ if and only if for every
pair $(x_1,x_2)$ there is a single $\theta$ with $p^{(1)}_\theta(x_1) = \ph^{(1)}(x_1)$
and $p^{(2)}_\theta(x_2) = \ph^{(2)}(x_2)$ --- a \emph{common maximiser}.
\end{theorem}

\begin{proof}
($\Rightarrow$) Equality of sums forces equality in Lemma~\ref{lem:tiedpt} at every pair.
Finiteness gives a $\theta_0$ attaining the tied envelope, so
$p^{(1)}_{\theta_0}(x_1)p^{(2)}_{\theta_0}(x_2) = \ph^{(1)}(x_1)\ph^{(2)}(x_2)$. If both
block envelopes are positive, the factorwise bounds and equality of products force
equality in each factor; if a block envelope vanishes, every parameter maximises that
block and the condition is vacuous there. ($\Leftarrow$) A common maximiser makes the
pointwise bound an equality at that pair.
\end{proof}

\begin{theorem}[Strictness from one deficient outcome; no finiteness needed]\label{thm:tiedstrict}
If $\ph(x_1,x_2) < \ph^{(1)}(x_1)\ph^{(2)}(x_2)$ for a single pair $(x_1,x_2)$, then
$C_S(\mathrm{tied}) < C_S^{(1)}C_S^{(2)}$.
\end{theorem}

\begin{proof}
A sum of pointwise inequalities with one strict term is strict.
\end{proof}

Theorem~\ref{thm:tiedstrict} is the workhorse for continuous parameter spaces, where
maximisers need not exist and Theorem~\ref{thm:tiedeq} does not apply.

\subsection{A worked extremal family}

Let the \emph{point-mass class} have message space $\A$, parameter space $\A$, and source
$a$ putting all its mass on the message $a$. Its envelope is identically $1$, so
$C_S = m$: the upper endpoint, as Theorem~\ref{thm:upper} predicts. The tied product of
two copies has envelope $\mathbf{1}[x_1=x_2]$ on $\A\times\A$, so
$C_S(\mathrm{tied}) = m$ whereas $C_S^{(1)}C_S^{(2)} = m^2$: for $m\ge2$ a strict gap,
exactly as Theorem~\ref{thm:tiedeq} predicts, since the outcome pair $(a,b)$ with $a\ne b$
has no common maximiser. Tying saves $\log_2 m$ of the $2\log_2 m$ bits.

\section{The memoryless class: strict subadditivity}

Throughout, $m = |\A| \ge 2$.

\begin{lemma}\label{lem:const}
For every $n$ and letter $a$, $p_{\delta_a}(a^n) = 1$, hence $\ph(a^n) = 1$. Moreover for
$n\ge1$, $p_\theta(a^n) = 1$ implies $\theta(a) = 1$.
\end{lemma}

\begin{proof}
$p_\theta(a^n) = \theta(a)^n$; envelopes never exceed $1$, and $\theta(a)<1$ with $n\ge1$
gives $\theta(a)^n < 1$.
\end{proof}

\begin{theorem}[Length one is at the upper endpoint]\label{thm:one}
$C_S(1) = m$.
\end{theorem}

\begin{proof}
Every one-symbol message is a constant string, so by Lemma~\ref{lem:const} the envelope is
identically $1$; summing over the $m$ messages gives $m$.
\end{proof}

\begin{theorem}[Block isomorphism]\label{thm:blocks}
For all $n_1,n_2\ge0$, the memoryless class of length $n_1+n_2$ and the tied product of
the memoryless classes of lengths $n_1$ and $n_2$ have the same Shtarkov sum.
\end{theorem}

\begin{proof}
Splitting positions into the first $n_1$ and last $n_2$ is a bijection
$\A^{n_1+n_2}\cong\A^{n_1}\times\A^{n_2}$ under which likelihoods correspond, since
$\prod_{i\le n_1+n_2}\theta(x_i) = \prod_{i\le n_1}\theta(x_i)\cdot\prod_{j\le n_2}\theta(x_{n_1+j})$
for every $\theta$. A likelihood-preserving bijection preserves envelopes, hence Shtarkov
sums; comparing in both directions gives equality.
\end{proof}

\begin{theorem}[Quarter bound]\label{thm:quarter}
Let $n_1,n_2\ge1$ and $a\ne b$. In the tied product of the length-$n_1$ and length-$n_2$
memoryless classes,
\[
\ph\big(a^{n_1},b^{n_2}\big) \;\le\; \tfrac14,
\qquad\text{while}\qquad
\ph^{(1)}(a^{n_1})\,\ph^{(2)}(b^{n_2}) = 1 .
\]
\end{theorem}

\begin{proof}
For any $\theta$ the tied likelihood is $\theta(a)^{n_1}\theta(b)^{n_2}$. Since
$0\le\theta(a)\le1$ and $n_1\ge1$ we have $\theta(a)^{n_1}\le\theta(a)$, and likewise for
$b$. As $a\ne b$, $\theta(a)+\theta(b)\le1$, so by the arithmetic--geometric mean
inequality $\theta(a)\theta(b) \le \big(\tfrac{\theta(a)+\theta(b)}2\big)^2 \le \tfrac14$.
Take the supremum over $\theta$; the second claim is Lemma~\ref{lem:const}.
\end{proof}

The essential content is that the deficiency is bounded away from zero \emph{uniformly in
the block lengths}, which is what a continuous parameter space demands.

\begin{theorem}[Strict submultiplicativity]\label{thm:strict}
For $m\ge2$ and $n_1,n_2\ge1$, $\;C_S(n_1+n_2) < C_S(n_1)\,C_S(n_2)$.
\end{theorem}

\begin{proof}
By Theorem~\ref{thm:blocks} the left side is the Shtarkov sum of the tied product. Choose
$a\ne b$. By Theorem~\ref{thm:quarter} the tied envelope at $(a^{n_1},b^{n_2})$ is at most
$1/4 < 1$, the product of the block envelopes there. Theorem~\ref{thm:tiedstrict}, which
needs no finiteness, converts this single strict pointwise inequality into a strict
inequality of sums.
\end{proof}

\begin{corollary}[Bit form]
For $m\ge2$ and $n_1,n_2\ge1$,
$\log_2 C_S(n_1+n_2) < \log_2 C_S(n_1) + \log_2 C_S(n_2)$: the price of universality of a
memoryless source is strictly subadditive in the block length.
\end{corollary}

\begin{theorem}[Compounding gain]
For $m\ge2$ and every $n\ge2$, $\;C_S(n) < m^n$.
\end{theorem}

\begin{proof}
Induction. For $n=2$, Theorem~\ref{thm:strict} with $n_1=n_2=1$ and Theorem~\ref{thm:one}
give $C_S(2) < m^2$. If $C_S(n) < m^n$, then Theorem~\ref{thm:strict} with $(n,1)$ and
Theorem~\ref{thm:one} give $C_S(n+1) < C_S(n)\cdot m < m^{n+1}$.
\end{proof}

\begin{remark}
The quantity $m^n$ is what one would pay if each symbol carried its own free parameter:
$n$ independent copies of the length-one problem, each at the maximal price $m$, for a
regret linear in $n$. The theorem says tying always wins, strictly, and the win is
realised afresh at every split. This is the qualitative content behind the classical
asymptotics $\log_2 C_S(n) = \frac{m-1}{2}\log_2 n + O(1)$: the exponential price of
``one parameter per symbol'' collapses to a polynomial one because the blocks are tied.
\end{remark}

\section{The sufficient-statistic bound}

A map $T:\X\to\sigma$ into a finite set is a \emph{sufficient statistic} if $T(x)=T(y)$
implies $p_\theta(x)=p_\theta(y)$ for every $\theta$.

\begin{lemma}[Fibrewise unit bound]
For a sufficient statistic and each value $s$, $\sum_{x:T(x)=s}\ph(x) \le 1$.
\end{lemma}

\begin{proof}
On a non-empty fibre all likelihoods, hence the envelope, are constant; if the fibre has
$\kappa$ elements with representative $x_0$, then $\kappa\,p_\theta(x_0) \le 1$ for every
$\theta$, so $\ph(x_0)\le1/\kappa$ and the fibre sum is at most $1$.
\end{proof}

Summing over $s$ recovers $C_S \le |\sigma|$: the price never exceeds the logarithm of the
number of \emph{types}. For the memoryless class the empirical letter-count vector is
sufficient, and there are $\binom{n+m-1}{m-1} = O(n^{m-1})$ types.

\begin{theorem}[Equality case]
$C_S = |\sigma|$ if and only if every fibre of $T$ carries exactly unit envelope mass.
\end{theorem}

\begin{proof}
Decompose $C_S$ over the level sets of $T$; the total equals $|\sigma|$ iff each of the
$|\sigma|$ fibre sums, each at most $1$, equals $1$.
\end{proof}

\section{Algorithms and numerics}

For a memoryless block with letter counts $(k_a)$, $\sum_a k_a = n$, the maximum-likelihood
parameter is the empirical distribution $\hat\theta(a) = k_a/n$ and
$\ph(x) = \prod_a (k_a/n)^{k_a}$ (with $0^0 = 1$). Since the counts are sufficient, one
sums over types rather than strings:
\[
C_S(n) \;=\; \sum_{\substack{(k_a)\ge0\\ \sum_a k_a = n}}
\binom{n}{k_{a_1},\dots,k_{a_m}} \prod_a \Big(\frac{k_a}{n}\Big)^{k_a},
\]
a sum of $\binom{n+m-1}{m-1}$ terms rather than $m^n$, evaluable exactly in rational
arithmetic. For $m=2$:

\begin{center}
\begin{tabular}{lccccc}
\toprule
$n$ & 1 & 2 & 3 & 4 & 5\\
\midrule
$C_S(n)$ & $2$ & $5/2$ & $26/9$ & $103/32$ & $2194/625$\\
$2^n$ & $2$ & $4$ & $8$ & $16$ & $32$\\
ratio & $1$ & $1.60$ & $2.77$ & $4.97$ & $9.11$\\
\bottomrule
\end{tabular}
\end{center}

The ratio grows without bound --- $C_S(n)\sim\sqrt{\pi n/2}$ for $m=2$ --- so the strict
inequality $C_S(n)<2^n$ is true but very lossy. For a finite class given by a table of
rational probabilities, $C_S$, $\Omega$ and all pairwise total variation distances are
computed in $O(k|\X|)$ and $O(k^2|\X|)$ operations. Representative exact checks:
$p=(1/2,1/3,1/6)$ against $q=(1/4,1/4,1/2)$ gives $C_S = 4/3 = 1+\dTV$; three copies of the
uniform law on three letters give $C_S = 1$, $\Omega = 2$, $C_S+\Omega = 3$; an exhaustive
sweep of all $8^3$ classes of three sources on three letters drawn from a fixed
eight-element palette found the predicate $C_S = 3$ equivalent to mutual singularity in
every case; and the tied product of two point-mass blocks on two letters gives
$C_S(\mathrm{tied}) = 2$ against $C_S\cdot C_S = 4$.

\section{Applications}

\paragraph{Model selection.} $\log_2 C_S$ is the parametric complexity term of the minimum
description length principle: the normalised maximum likelihood codelength of $x$ is
$\log_2(1/\ph(x)) + \log_2 C_S$. Rigidity of the maximal price identifies the classes whose
complexity term is maximal (mutually singular families are as complex as a lookup table),
while the stability bound says that near-duplicated members contribute strictly less than a
full unit of complexity --- a quantitative version of the intuition that redundant
parametrisations should not be penalised twice.

\paragraph{Sequential prediction.} $\log_2 C_S$ is the minimax cumulative regret of
probability forecasting against the best model in hindsight, so strict subadditivity says
that merging two prediction phases into one tied problem always saves regret.

\paragraph{Compression.} The compounding-gain theorem is the formal statement that a code
sharing one parameter across the block strictly beats a per-symbol adaptive code, at every
block length, on every alphabet with at least two letters.

\section{Discussion and open problems}

Two mechanisms carry the whole analysis. First, the conservation law $C_S+\Omega=k$ turns
the upper bound into an identity, so every statement near the top is a statement about the
shared mass. Second, essentially every inequality in the subject --- the upper bound, the
tied-product bound, the monotonicity bound, the type bound --- is a \emph{sum of pointwise
inequalities}: equality is equivalent to pointwise equality everywhere, and a single strict
term suffices for strictness. The one genuine subtlety is the passage to continuous
parameter spaces: the criterion ``every outcome pair has a common maximiser'' extracts an
attaining parameter and hence needs finiteness, while its quantitative replacement --- a
uniform envelope deficiency at a single outcome pair --- is weaker as a criterion but
strictly more applicable.

\paragraph{Sharp constant in all-pairs stability.} The proved bound is
$\sum_{\theta\ne\theta'}(1-\dTV(p_\theta,p_{\theta'})) \le k(k-1)\Omega$. It is conjectured
that the constant improves to $2(k-1)$, sharply, with the family of two coincident sources
among $k$ as the extremal case. At a fixed message, sorting the likelihoods
$a_1\ge\cdots\ge a_k$ turns the pair sum into $2\sum_j (j-1)a_j$, dominated by the
non-maximal mass $\sum_{j\ge2}a_j$ up to $2(k-1)$; the crude proof discards the ordering and
pays an extra factor $k$. A monotone-rearrangement argument at each message is what is
missing.

\paragraph{Rigidity for the redundancy--capacity inequality.} The equality case of
$I(w) \le \log_2 C_S$, for a prior $w$ on parameters, is untouched; unlike everything above
it is not a sum of pointwise inequalities and needs a Gibbs-type equality analysis.

\paragraph{Quantifying the memoryless deficit.} The true behaviour is
$C_S(n) = \Theta(n^{(m-1)/2})$, while the pointwise method gives only a constant-factor gain
per split. Recovering the correct polynomial order by exhibiting deficiencies at many
outcome pairs would be a substantial quantitative upgrade.

\paragraph{Beyond memorylessness.} The tied-product machinery ignores the internal structure
of blocks, so the strictness argument should transfer to Markov chains, tree sources and
exponential families; the concrete task is identifying, for each model class, a pair of
block outcomes whose separate maximisers provably conflict with a uniform gap.

\paragraph{Stability under perturbation.} A two-sided Lipschitz estimate for $C_S$ as a
functional of the class, in a suitable metric on families, is missing; the total-variation
bounds above are first steps.

\end{document}

