function MEMORYLESS-SHTARKOV(n, m):
    if n = 0: return 1
    total <- 0
    for each type (k_1, ..., k_m) with k_a >= 0 and sum_a k_a = n:
        size     <- n! / (k_1! * ... * k_m!)          # words of this type
        envelope <- product over a with k_a > 0 of (k_a / n)^{k_a}
        total    <- total + size * envelope           # exact rationals
    return total

function SUBADDITIVITY-TABLE(m, N):
    for n in 1 .. 2N: C[n] <- MEMORYLESS-SHTARKOV(n, m)
    for n1 in 1 .. N, n2 in 1 .. N:
        emit (n1, n2, log2 C[n1] + log2 C[n2] - log2 C[n1 + n2])
    # every emitted saving is strictly positive

