"""Exact evaluation of the memoryless Shtarkov sum by the method of types."""

from __future__ import annotations

import math
from fractions import Fraction
from typing import Iterable, List, Sequence, Tuple


def compositions(n: int, m: int) -> Iterable[Tuple[int, ...]]:
    """Enumerate all non-negative integer vectors of length m summing to n.

    These index the *types* (empirical letter-count vectors) of length-n words
    over an m-letter alphabet; there are C(n + m - 1, m - 1) of them.
    """
    if m == 1:
        yield (n,)
        return
    for first in range(n + 1):
        for rest in compositions(n - first, m - 1):
            yield (first,) + rest


def multinomial(counts: Sequence[int]) -> int:
    """Size of the type class: number of words with the given letter counts."""
    value = math.factorial(sum(counts))
    for c in counts:
        value //= math.factorial(c)
    return value


def type_envelope(counts: Sequence[int]) -> Fraction:
    """Maximum-likelihood envelope of any word of this type.

    The maximiser of prod_i theta(x_i) over the simplex is the empirical
    distribution theta_hat(a) = k_a / n, giving prod_a (k_a / n)^{k_a}
    with the convention 0^0 = 1.
    """
    n = sum(counts)
    value = Fraction(1)
    for c in counts:
        if c > 0:
            value *= Fraction(c, n) ** c
    return value


def memoryless_shtarkov_sum(n: int, m: int) -> Fraction:
    """Exact C_S(n) = sum over types of (type size) x (type envelope)."""
    if n == 0:
        return Fraction(1)
    return sum(
        (Fraction(multinomial(t)) * type_envelope(t) for t in compositions(n, m)),
        Fraction(0),
    )


def price_in_bits(n: int, m: int) -> float:
    """log2 C_S(n): the minimax pointwise regret of the memoryless class."""
    return math.log2(float(memoryless_shtarkov_sum(n, m)))


def subadditivity_table(m: int, max_n: int) -> List[Tuple[int, int, float]]:
    """Saving in bits at each split: log2 C(n1) + log2 C(n2) - log2 C(n1+n2)."""
    cache = {n: memoryless_shtarkov_sum(n, m) for n in range(1, 2 * max_n + 1)}
    rows: List[Tuple[int, int, float]] = []
    for n1 in range(1, max_n + 1):
        for n2 in range(1, max_n + 1):
            saving = (math.log2(float(cache[n1])) + math.log2(float(cache[n2]))
                      - math.log2(float(cache[n1 + n2])))
            rows.append((n1, n2, saving))
    return rows


if __name__ == "__main__":
    for m in (2, 3, 4):
        print(f"alphabet size m = {m}")
        for n in range(1, 9):
            cs = memoryless_shtarkov_sum(n, m)
            print(f"  n = {n}:  C_S = {cs} = {float(cs):.6f}"
                  f"   (m^n = {m ** n}, price {math.log2(float(cs)):.4f} bits)")
        print("  savings at splits (bits):")
        for n1, n2, s in subadditivity_table(m, 3):
            print(f"    ({n1},{n2}) -> {s:.6f}")
